class Solution {
  public int minimumSwaps(int[] nums) {
    int zeros = 0;
    for (int x : nums) if (x == 0) zeros++;
    // each swap fixes one zero sitting in the first n - zeros slots
    int swaps = 0;
    for (int i = 0; i < nums.length - zeros; i++) if (nums[i] == 0) swaps++;
    return swaps;
  }
}
